import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n1 = int(next(iterator))
        n2 = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    edges = []
    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        edges.append((u, v, i + 1))

    adj_u = [[] for _ in range(n1 + 1)]
    adj_v = [[] for _ in range(n2 + 1)]

    for idx, (u, v, eid) in enumerate(edges):
        adj_u[u].append((v, idx))
        adj_v[v].append((u, idx))

    deg_u = [len(adj_u[i]) for i in range(n1 + 1)]
    deg_v = [len(adj_v[i]) for i in range(n2 + 1)]

    min_degree = 0
    if n1 > 0:
        min_degree = min(deg_u[1:])
    if n2 > 0:
        min_degree = min(min_degree, min(deg_v[1:]))
    else:
        min_degree = 0

    results = []

    current_edges = set(range(m))

    for k in range(min_degree + 1):
        if k == 0:
            results.append((0, []))
            continue

        current_deg_u = list(deg_u)
        current_deg_v = list(deg_v)
        used = [True] * m

        q = deque()

        for i in range(1, n1 + 1):
            if current_deg_u[i] < k:
                q.append(('u', i))
        for j in range(1, n2 + 1):
            if current_deg_v[j] < k:
                q.append(('v', j))

        while q:
            side, node = q.popleft()

            if side == 'u':
                adj_list = adj_u[node]
                current_deg = current_deg_u
                other_side = 'v'
                other_adj = adj_v
                other_deg_ref = current_deg_v
            else:
                adj_list = adj_v[node]
                current_deg = current_deg_v
                other_side = 'u'
                other_adj = adj_u
                other_deg_ref = current_deg_u

            if current_deg[node] >= k:
                continue

            removed_edges = []
            for other_node, edge_idx in adj_list:
                if used[edge_idx]:
                    removed_edges.append((other_node, edge_idx))
                    used[edge_idx] = False
                    current_deg[node] -= 1
                    other_deg_ref[other_node] -= 1
                    if other_deg_ref[other_node] < k:
                        q.append((other_side, other_node))

            if current_deg[node] < k:
                pass

        selected = [edges[i][2] for i in range(m) if used[i]]
        results.append((len(selected), sorted(selected)))

    output_lines = []
    for cnt, edge_indices in results:
        if cnt == 0:
            output_lines.append("0")
        else:
            output_lines.append(f"{cnt} {' '.join(map(str, edge_indices))}")

    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == "__main__":
    solve()
